40	const { lesenBereit, zugriff, kontext, heute, E } = egIntern;
41	const SYS = () => ({ id: "system-eg", rollen: ["admin"], backofficeRollen: ["leitung"], system: true });
42	const AT = GEMEINSCHAFTEN.rechner.at;
43	const datumDe = (d) => String(d || "").split("-").reverse().join(".");
44	
45	/** Fachfehler der reinen Module → PlattformFehler */
46	function fach(fn) {
47	  try {
48	    return fn();
49	  } catch (e) {
50	    if (e instanceof MitgliedFehler) {
51	      const f = new PlattformFehler(e.status || 422, e.message);
52	      if (e.feld) f.feld = e.feld;
53	      throw f;
54	    }
55	    throw e;
56	  }
57	}
58	
59	/** Operation eines Nachbarpakets; 501 (noch nicht umgesetzt) bzw. Fehler → Leerzustand statt Abbruch */
60	async function versuch(fn) {
61	  try {
62	    return { ok: true, wert: await fn() };
63	  } catch (e) {
64	    const status = e?.status || 500;
65	    if (status !== 501) console.warn("[eg-portal] Nachbarpaket:", e?.message);
66	    return { ok: false, status, text: status === 501 ? "Diese Daten werden gerade angebunden." : status === 403 || status === 404 ? "Keine Daten freigegeben." : "Die Daten sind gerade nicht erreichbar." };
67	  }
68	}
69	
70	function portalDaten(db) {
71	  db.egPortal ||= { v: 1 };
72	  for (const k of ["interessen", "beitritte", "tfWuensche", "kuendigungen"]) db.egPortal[k] ||= [];
73	  return db.egPortal;
74	}
75	const P = (db) => ({ interessen: [], beitritte: [], tfWuensche: [], kuendigungen: [], ...(db.egPortal || {}) });
76	function anmelden(n) {
77	  if (!n || n.system) throw new PlattformFehler(401, "Bitte melden Sie sich an.");
78	}
79	
80	// ================================================================ Ausgabe-Helfer
81	
82	const nbVon = (db, id) => E(db).netzbetreiber.find((x) => x.id === id) || null;
83	const tarifVon = (db, gid) => tarifAm(E(db).tarife.filter((t) => t.gemeinschaftId === gid), heute());
84	function oeffentlich(db, g) {
85	  const x = E(db);
86	  const mitglieder = x.mitglieder.filter((m) => m.gemeinschaftId === g.id);
87	  const plz = [...mitglieder.map((m) => m.person?.plz), ...x.teilnahmen.filter((t) => t.gemeinschaftId === g.id).map((t) => x.zaehlpunkte.find((z) => z.id === t.zaehlpunktId)?.plz?.slice(1))];
88	  return gemeinschaftOeffentlich(g, { tarif: tarifVon(db, g.id), mitglieder: mitglieder.filter((m) => MITGLIED_AKTIV.includes(m.status)).length, plzBereich: plz, netzbetreiberNamen: (g.netzbetreiber || []).map((id) => nbVon(db, id)?.kurzname || id) });
89	}
90	const gemeinschaftKurz = (g) => ({ id: g.id, name: g.name, kurzname: g.kurzname, modell: g.modell, modellKurz: EG_MODELLE[g.modell]?.kurz || g.modell, modellLabel: EG_MODELLE[g.modell]?.label || g.modell, zonelevel: g.zonelevel, zonelevelLabel: ZONELEVEL[g.zonelevel]?.label || "", status: g.status, statusLabel: GEMEINSCHAFT_STATUS[g.status]?.label || g.status, ort: g.sitzAdresse?.ort || "", organisator: !!g.dienstleistung?.aktiv, demo: !!g.demo });
91	function mitgliedEigen(m) {
92	  return {
93	    id: m.id, gemeinschaftId: m.gemeinschaftId, mitgliedsnummer: m.mitgliedsnummer, art: m.art, artLabel: MITGLIED_ARTEN[m.art]?.label || m.art, name: mitgliedName(m), person: { ...m.person },
94	    status: m.status, statusLabel: MITGLIED_STATUS[m.status]?.label || m.status, ton: MITGLIED_STATUS[m.status]?.ton || "neutral", beitrittAm: m.beitrittAm, austrittZum: m.austrittZum,
95	    iban: ibanMaskiert(m.iban), sepaMandat: m.sepaMandat?.status ? { referenz: m.sepaMandat.referenz, datum: m.sepaMandat.datum, status: m.sepaMandat.status } : null, rechnungsweg: m.rechnungsweg, schutzbeduerftig: !!m.schutzbeduerftig,
96	  };
97	}
98	/** Eigene Teilnahmen eines Mitglied-Eintrags mit Zählpunkt, Schritten und (solange nötig) Anleitung zur Zustimmung */
99	function teilnahmenEigen(db, g, m) {
100	  const x = E(db);
101	  return x.teilnahmen.filter((t) => t.mitgliedId === m.id && t.gemeinschaftId === g.id && t.status !== "verworfen").map((t) => {
102	    const z = x.zaehlpunkte.find((y) => y.id === t.zaehlpunktId) || {};
