113	/** Preise für die Ersparnis-Schätzung (Tarif der Gemeinschaft, Netzentgelt-Regel, sonst Standardwerte aus markt.js) */
114	function preise(db, g, netzebene = 7) {
115	  const t = tarifVon(db, g.id);
116	  const regel = netzentgeltRegel({ datum: heute(), modell: g.modell, zonelevel: g.zonelevel, netzebene });
117	  const ap = (nbVon(db, g.netzbetreiber?.[0])?.netzentgeltAp || []).filter((x) => Number(x.netzebene) === netzebene).sort((a, b) => b.gueltigAb.localeCompare(a.gueltigAb))[0]?.ctKwh;
118	  return { bezugspreisCt: t?.bezugspreisCt ?? AT.gemeinschaftCt, einspeisepreisCt: t?.einspeisepreisCt ?? 0, lieferantCt: AT.energiepreis, netzApCt: ap ?? AT.netzAp, reduktionPct: regel.reduktionPct, abgabenBefreit: regel.abgabenBefreit, abgabenCt: AT.abgabenCt, co2KgJeKwh: RECHNER_STANDARD.co2KgJeKwh, regelText: regel.text, regelStatus: regel.status };
