120	/** Kennzahlen je Zeitraum aus den WP3-Periodenwerten (nur eigene Teilnahmen) */
121	async function energieFuer(db, g, eigene) {
122	  const zr = zeitraeume(heute());
123	  const ids = new Set(eigene.map((t) => t.id));
124	  const richtung = Object.fromEntries(eigene.map((t) => [t.id, t.richtung]));
125	  const p = preise(db, g);
126	  const werte = {};
127	  let fehlt = null;
128	  for (const [k, z] of Object.entries(zr)) {
129	    const r = await versuch(() => energie.enPeriodenwerte(SYS(), g.id, z.von, z.bis));
130	    if (!r.ok) {
131	      fehlt = r;
132	      werte[k] = null;
