136	    werte[k] = { ...z, ...energieKennzahlen(liste, p) };
137	  }
138	  return { zeitraeume: zr, werte, verfuegbar: !fehlt, hinweis: fehlt?.text || "", preise: { bezugspreisCt: p.bezugspreisCt, lieferantCt: p.lieferantCt, netzApCt: p.netzApCt, regel: p.regelText, regelStatus: p.regelStatus } };
