/** Dashboard-Daten (Seite /portal/admin/eg/[id]/energiedaten und Organ-Reiter): 13 Monate, 30 Tage, 7 Tage Viertelstunden */
export async function enDashboard(n, gemeinschaftId) {
  const h = heute();
