  for (const tag of tageDesMonats(monat)) {
    const d = tag < h ? tagDaten(db, g.id, tag, ov) : { bloecke: new Map() };
    const t = tarifAm(tarife, tag);
    const jeZp = {};
    for (const i of infos) {
      if (!i.teilnahmen.some((tt) => teilnahmeAktivAm(tt, tag))) continue;
