      }
      jeZp[i.zp.id] = x;
      beitragAddieren((summe[i.zp.id] ||= beitragLeer()), x);
    }
    tage[tag] = jeZp;
  }
  const daten = { tage, summe };
  if (periodenCache.size > 120) periodenCache.clear();
