	r = EDA.tf_aendern(gemeinschaftId=g["id"], daten={"aenderungen": [{"teilnahmeId": w["teilnahmeId"], "teilnahmefaktor": w["nach"], "ab": ab} for w in offen]}, als_benutzer=als_benutzer)
