// src/lib/plattform/eg/optimierung.js
//
// WP3: Mehrfachteilnahme-Optimierer (Fachkonzept 4.9; ElWG § 71 Abs. 5) – Empfehlung der Teilnahmefaktoren eines
// Zählpunkts über bis zu 5 Gemeinschaften. Reine Funktionen, Python-Spiegel: plattform/eg_energie_kern.py.
//
// maximiere Σ_k Wert_k(TF_k)  unter  Σ TF_k ≤ 100, TF_k ∈ {0} ∪ {1..100} ganzzahlig, höchstens 5 Gemeinschaften.
// Wert_k(t) = Σ_q geteilte Menge des Zählpunkts in Gemeinschaft k bei TF t × Vorteil_k (ct/kWh, inkl. Netzentgeltvorteil
// nach Zonelevel bzw. Preisspanne Einspeisung − Marktwert). Die geteilte Menge folgt dem dynamischen Modell (4.2):
//   Verbraucher:  V' = V·t/100; ED = min(V', E_k · V'/(D_k + V'))  (E_k Erzeugung, D_k Verbrauch der übrigen Teilnehmer)
//   Erzeuger:     E' = P·t/100; G = min(E_k + E', D_k) · E'/(E_k + E')
// Statt Greedy (setzt Konkavität voraus) wird EXAKT per dynamischer Programmierung über das TF-Budget optimiert
// (K ≤ 5, Budget 100 → vernachlässigbarer Aufwand). Rechengrundlage: repräsentative Viertelstunden (z. B. je Monat eine
// Woche), hochgerechnet auf ein Jahr. Umsetzung über EC_PRTFACT_CHG (WP2), derzeit 1 Änderung je Tag (bis 01.04.2028).

import { MAX_TEILNAHMEN_JE_ZP } from "./modell.js";
import { energieFehler, rund } from "./messwerte.js";

/** Geteilte Menge (kWh) eines Zählpunkts in einer Gemeinschaft bei Teilnahmefaktor t */
export function geteilteMenge(richtung, werte, k, t) {
  const f = t / 100;
  const E = k.erzeugung || [];
  const D = k.verbrauch || [];
  let s = 0;
  for (let q = 0; q < werte.length; q++) {
    const x = (werte[q] || 0) * f;
    if (x <= 0) continue;
    const e = E[q] || 0;
    const d = D[q] || 0;
    if (richtung === "verbrauch") {
      const v = d + x;
      s += e >= v ? x : (e * x) / v;
    } else {
      const g = e + x;
      s += (Math.min(g, d) * x) / g;
    }
  }
  return s;
}

/**
 * TF-Empfehlung.
 * @param {{richtung:"verbrauch"|"erzeugung", werte:number[], hochrechnung?:number,
 *          kandidaten:{gemeinschaftId:string, label?:string, vorteilCtKwh:number, erzeugung:number[], verbrauch:number[], aktuellTf?:number}[]}} e
 */
			"gruenFenster": gruene_fenster(stunden), "besteStunde": beste["stunde"] if beste else None, "stunden": stunden,
		})
	return {"heute": heute, "kalibrierung": rund(kal, 4), "tageHistorie": len(letzte30), "verhaeltnisP10": rund(p10, 4), "verhaeltnisP90": rund(p90, 4), "tage": erg, "hinweis": "Prognose aus Klimamittel und Messhistorie der letzten 30 Tage; mit Wettervorhersage genauer. Nur Empfehlung, keine Steuerung."}


# ---------------------------------------------------------------- Mehrfachteilnahme-Optimierer (4.9)


def geteilte_menge(richtung, werte, k, t):
	f = t / 100
	E = k.get("erzeugung") or []
	D = k.get("verbrauch") or []
	s = 0.0
	for q in range(len(werte)):
		x = (werte[q] or 0) * f
		if x <= 0:
			continue
		e = (E[q] if q < len(E) else 0) or 0
		d = (D[q] if q < len(D) else 0) or 0
		if richtung == "verbrauch":
			v = d + x
			s += x if e >= v else (e * x) / v
		else:
			g = e + x
			s += (min(g, d) * x) / g
	return s


def tf_optimieren(richtung="verbrauch", werte=None, kandidaten=None, hochrechnung=1):
	werte = werte or []
	kandidaten = kandidaten or []
	if richtung not in ("verbrauch", "erzeugung"):
		raise energie_fehler("Richtung verbrauch oder erzeugung.", "richtung")
	if not kandidaten:
		raise energie_fehler("Keine Gemeinschaft zur Auswahl.", "kandidaten")
	if len(kandidaten) > MAX_TEILNAHMEN_JE_ZP:
		raise energie_fehler(f"Höchstens {MAX_TEILNAHMEN_JE_ZP} Gemeinschaften je Zählpunkt (ElWG § 71 Abs. 5).", "kandidaten")
	K = len(kandidaten)
	kurven = []
	for k in kandidaten:
		c = [0.0] * 101
		for t in range(1, 101):
			c[t] = (geteilte_menge(richtung, werte, k, t) * hochrechnung * (k.get("vorteilCtKwh") or 0)) / 100
		kurven.append(c)
	best = [[0.0] * 101 for _ in range(K + 1)]
	wahl = [[0] * 101 for _ in range(K + 1)]
	for k in range(1, K + 1):
		for b in range(101):
			bw = best[k - 1][b]
			bt = 0
			for t in range(1, b + 1):
				x = best[k - 1][b - t] + kurven[k - 1][t]
				if x > bw + 1e-12:
					bw = x
					bt = t
			best[k][b] = bw
			wahl[k][b] = bt
	tf = [0] * K
	b = 100
	for k in range(K, 0, -1):
		tf[k - 1] = wahl[k][b]
		b -= wahl[k][b]

	def menge(i, t):
		return geteilte_menge(richtung, werte, kandidaten[i], t) * hochrechnung if t else 0

	aktuell = [max(0, min(100, _js_round(_f(k.get("aktuellTf") or 0)))) for k in kandidaten]
	aktuell_wert = 0.0
	for i, t in enumerate(aktuell):
		aktuell_wert += kurven[i][t]
	wert = 0.0
	for i, t in enumerate(tf):
		wert += kurven[i][t]
	empfehlung = []
	for i, k in enumerate(kandidaten):
		empfehlung.append({
			"gemeinschaftId": k["gemeinschaftId"], "label": k.get("label") or k["gemeinschaftId"], "vorteilCtKwh": k.get("vorteilCtKwh"), "aktuellTf": aktuell[i], "empfohlenTf": tf[i],
			"geteiltKwh": rund(menge(i, tf[i]), 3), "wertEur": rund(kurven[i][tf[i]], 2), "aktuellGeteiltKwh": rund(menge(i, aktuell[i]), 3), "aktuellWertEur": rund(kurven[i][aktuell[i]], 2),
			"kurve": [{"tf": t, "wertEur": rund(kurven[i][t], 2)} for t in range(0, 101, 10)],
		})
	gesamt = 0.0
	for x in werte:
		gesamt += x or 0
	gesamt *= hochrechnung
	summe_tf = sum(tf)
	hinweise = [
		"Teilnahmefaktoren ganzzahlig 1–100 %, Summe höchstens 100 %, bis zu 5 Gemeinschaften (ElWG § 71 Abs. 5).",
		"Änderung über EC_PRTFACT_CHG, derzeit einmal je Tag und Gemeinschaft (ab 01.04.2028 mehrmals täglich, zu bestätigen).",
	]
	if summe_tf < 100:
		hinweise.append(f"{100 - summe_tf} % bleiben ohne Gemeinschaft – dort lohnt keine weitere Teilnahme (Grenznutzen 0).")
	hinweise.append("Empfehlung auf Basis repräsentativer Viertelstunden; fremde Gemeinschaften nur mit Daten, die das Mitglied selbst bereitstellt.")
	return {"richtung": richtung, "empfehlung": empfehlung, "summeTf": summe_tf, "restTf": 100 - summe_tf, "wertEur": rund(wert, 2), "aktuellWertEur": rund(aktuell_wert, 2), "verbesserungEur": rund(wert - aktuell_wert, 2), "mengeKwh": rund(gesamt, 3), "aenderungen": len([x for x in empfehlung if x["aktuellTf"] != x["empfohlenTf"]]), "hinweise": hinweise}


def repraesentative_tage(tage):
	je = {}
	for t in tage:
		m = t[:7]
		je.setdefault(m, [])
		if len(je[m]) < 7:
			je[m].append(t)
	auswahl = sorted(x for v in je.values() for x in v)
	return {"tage": auswahl, "hochrechnung": 365 / len(auswahl) if auswahl else 1}
  // ---- Optimierung
  const optW = reihe(96 * 4, (q) => Math.max(0, Math.sin((((q % 96) - 24) / 48) * Math.PI)) * 6);
  const kand = [
    { gemeinschaftId: "EEG", label: "EEG lokal", vorteilCtKwh: 4, aktuellTf: 60, erzeugung: reihe(96 * 4, (q) => Math.max(0, Math.sin((((q % 96) - 24) / 48) * Math.PI)) * 10), verbrauch: reihe(96 * 4, () => 5) },
    { gemeinschaftId: "BEG", label: "BEG", vorteilCtKwh: 3, aktuellTf: 40, erzeugung: reihe(96 * 4, () => 0), verbrauch: reihe(96 * 4, () => 20) },
    { gemeinschaftId: "P2P", label: "P2P", vorteilCtKwh: 6, aktuellTf: 0, erzeugung: reihe(96 * 4, () => 0), verbrauch: reihe(96 * 4, () => 0.5) },
  ];
  const optVerbr = { richtung: "verbrauch", werte: reihe(96 * 4, () => 1), kandidaten: [{ gemeinschaftId: "A", vorteilCtKwh: 5, erzeugung: reihe(96 * 4, (q) => (q % 96 > 40 && q % 96 < 60 ? 30 : 0)), verbrauch: reihe(96 * 4, () => 10), aktuellTf: 100 }, { gemeinschaftId: "B", vorteilCtKwh: 2, erzeugung: reihe(96 * 4, () => 3), verbrauch: reihe(96 * 4, () => 1), aktuellTf: 0 }], hochrechnung: 365 / 4 };
  const optimierung = {
    erzeugung: { eingabe: { richtung: "erzeugung", werte: optW, kandidaten: kand, hochrechnung: 365 / 4 }, aus: O.tfOptimieren({ richtung: "erzeugung", werte: optW, kandidaten: kand, hochrechnung: 365 / 4 }) },
    verbrauch: { eingabe: optVerbr, aus: O.tfOptimieren(optVerbr) },
    stichprobe: (() => {
      const t = [];
      for (let d = "2025-10-01"; d < "2026-10-01"; d = M.plusTag(d)) t.push(d);
      const r = O.repraesentativeTage(t);
      return { anzahl: r.tage.length, erste: r.tage.slice(0, 3), hochrechnung: r.hochrechnung };
    })(),
    fehler: fehlerVon(() => O.tfOptimieren({ richtung: "verbrauch", werte: [], kandidaten: [] })),
  };

  return { stand: "2026-10-01", quelle: "scripts/eg-energie-testdaten.mjs", zeit, verteilung, bloecke, csv, qualitaet, simulation, speicher, prognose: prognoseV, optimierung };
		p = V["prognose"]
		e = p["eingabe"]
		gleich(k.prognose(e["heute"], e["historie"], e["anlagen"], e["standort"], e["tage"], e["wetter"]), p["aus"], "prognose", 1e-7, 2e-3)

	def test_optimierung(self):
		for name in ("erzeugung", "verbrauch"):
			o = V["optimierung"][name]
			e = o["eingabe"]
			gleich(k.tf_optimieren(e["richtung"], e["werte"], e["kandidaten"], e["hochrechnung"]), o["aus"], name, 1e-9, 1e-6)
		t = []
		d = "2025-10-01"
		while d < "2026-10-01":
			t.append(d)
			d = k.plus_tag(d)
		r = k.repraesentative_tage(t)
		st = V["optimierung"]["stichprobe"]
		self.assertEqual(len(r["tage"]), st["anzahl"])
		self.assertEqual(r["tage"][:3], st["erste"])
		self.assertAlmostEqual(r["hochrechnung"], st["hochrechnung"], 12)
		gleich(fehler_von(k.tf_optimieren, "verbrauch", [], []), V["optimierung"]["fehler"])


if __name__ == "__main__":
	unittest.main()

