    const liste = (l) => (Array.isArray(l) ? l.slice(0, 5000).map((x) => ({ schluessel: String(x.schluessel || ""), name: String(x.name || ""), kwh: Number(x.kwh) || 0, betragEur: Number(x.betragEur) || 0 })).filter((x) => x.schluessel) : []);
